    def lexicographical_topological_sort(G, key=None):
        """Generate the nodes in the unique lexicographical topological sort order."""
        if not G.is_directed():
            raise NetworkXError("Topological sort not defined on undirected graphs.")

        if key is None:
            def key(node):
                return node

        nodeid_map = {n: i for i, n in enumerate(G)}

        def create_tuple(node):
            return key(node), nodeid_map[node], node

        indegree_map = {v: d for v, d in G.in_degree() if d > 0}
        zero_indegree = [create_tuple(v) for v, d in G.in_degree() if d == 0]
        heapq.heapify(zero_indegree)

        while zero_indegree:
            _, _, node = heapq.heappop(zero_indegree)

            if node not in G:
                raise RuntimeError("Graph changed during iteration")
            for _, child in G.edges(node):
                try:
                    indegree_map[child] -= 1
                except KeyError as err:
                    raise RuntimeError("Graph changed during iteration") from err
                if indegree_map[child] == 0:
                    try:
                        heapq.heappush(zero_indegree, create_tuple(child))
                    except TypeError as err:
                        raise TypeError(
                            f"{err}\nConsider using `key=` parameter to resolve ambiguities."
                        )
                    del indegree_map[child]

            yield node

        if indegree_map:
